sys_variable_value.value:
(function execute(inputs, outputs) {

    var serviceId = inputs.service;

    var gr = new GlideRecord('x_snc_queuesmart_queue');
    gr.addQuery('service', serviceId);
    gr.addQuery('status', 'IN', 'Waiting,Called,Serving');
    gr.orderByDesc('queue_position');
    gr.setLimit(1);
    gr.query();

    var lastPosition = 0;

    if (gr.next()) {
        lastPosition = parseInt(gr.queue_position, 10) || 0;
    }

    outputs.last_queue_position = lastPosition + 1;

})(inputs, outputs);

